-- Reemplaza el catálogo de la Federación Mexicana de Golf por un
-- directorio más amplio tomado del mapa de gogolf.mx (capa "Directorio
-- adicional", 194 clubes que no tenían ya equivalente en el catálogo).
--
-- Paso 1: borra los clubes que solo venían de la Federación y NO tienen
-- equivalente en el nuevo directorio — pero solo si nadie los está usando
-- ya (ninguna oferta, perfil o membresía los referencia). Si alguno sigue
-- en uso, se deja tal cual para no romper datos reales.
delete from public.clubs
where nombre in (
  'El Cortés Golf Club',
  'Punta Mita Golf Club',
  'Bajamar Golf & Resort',
  'Palma Real Golf & Beach Club',
  'Danzante Bay Golf Club',
  'Moon Palace Spa & Club Golf',
  'PGA Riviera Maya',
  'Tres Vidas Golf Club Acapulco',
  'Mayan Palace Golf',
  'Princess Golf Course - Mundo Imperial',
  'The Lakes Course at Vidanta Nuevo Vallarta',
  'Vidanta Greg Norman Golf Course',
  'El Camaleón Golf Course at Mayakoba',
  'Zibatá Golf',
  'Club de Golf y Deportivo Las Aves',
  'Gary Player Signature Golf Club El Cortés',
  'Club Refineria Madero',
  'Coral Golf Resort',
  'Club de Golf de Zacatecas',
  'Campestre el Cristo',
  'Altozano El Nuevo Colima',
  'Las Cruces Golf',
  'Puerto Cancún Golf Club',
  'Punta Tiburón Country Club',
  'Ciudad Del Sol Club de Golf',
  'Campeche Country Club',
  'Río Grande Country Club',
  'Alquerías Club de Golf',
  'Club Campestre de Reynosa',
  'Paraíso Country Club',
  'NAUKA',
  'Club de Golf El Socorro A.C.',
  'Club Campestre Juarez',
  'Club Campestre Celaya S.A. De C.V.',
  'Club Campestre Cordobés',
  'Club de Golf Campestre de Morelia',
  'Club de Golf San Carlos S.A. de C.V.',
  'Golf club Vallescondido',
  'Golf Juriquilla',
  'Club Campestre de Tuxtla',
  'Club de Golf las Fuentes',
  'Vista Verde Country Club',
  'Missions Club Campestre',
  'Club Campestre El Campanario B.C.',
  'Bosques Club De Golf',
  'Altozano Morelia Golf Bosque Monarca',
  'Tajin Golf Club',
  'Balvanera Polo Golf & Country Club',
  'Country Club Mante',
  'Tres Marias Golf Club',
  'Club de Golf la Herradura',
  'Club de Golf Las Lomas Zapopan',
  'Club de Golf de Cuernavaca',
  'La Loma Residential & Golf Club',
  'Altozano El Nuevo Tabasco',
  'Asturian Center of Mexico Club Campestre Ecological',
  'Club de Golf EL Molino',
  'Bosque Real Golf Course 9 Hole Course'
)
and not exists (select 1 from public.tee_time_offers where club_id = clubs.id)
and not exists (select 1 from public.profiles where club_id = clubs.id)
and not exists (select 1 from public.profile_clubs where club_id = clubs.id);

-- Paso 2: inserta los clubes nuevos. Los que ya existan por nombre
-- (incluidos los ~49 de la Federación que coinciden con este directorio,
-- y que por lo tanto NO se borraron arriba) se saltan gracias a la
-- restricción única de 0004_limpieza_duplicados.sql.
on conflict (nombre) do nothing;
